 if(c==='rf-excluded'){const a=pick(r,-5,-1),d=pick(r,1,6),coef=pick(r,2,5);if(s==='numeric')return num(RF,`What value is excluded from (x²+1)/(${coef}x−${coef*d})?`,d,[[0,'The denominator is not zero at x=0 unless the constant vanishes.'],[-d,'This reverses the sign when solving the denominator equation.']],`Set the denominator equal to zero to obtain x=${d}.`);return mcq(r,RF,`What values are excluded from (x+1)/((x−${a})(x−${d}))?`,[`${a} and ${d}`,'Each denominator factor must stay nonzero.'],[[`${-a} and ${-d}`,'The factor zeros use the opposite sign from the printed constants.'],[`${a} only`,'Both denominator factors create restrictions.'],['No values','A rational expression is not defined where its denominator is zero.']]);}
