 if(c==='rf-simplify'){const a=pick(r,2,6),d=pick(r,1,5);if(s==='numeric')return num(RF,`Simplify (${a}x+${a*d})/(x+${d}). What constant remains?`,a,[[a*d,'This is the numerator constant, not the factored quotient.'],[d,'This is the canceled shift, not the scale factor.']],`Factor ${a}(x+${d}) and cancel to obtain ${a}.`);if(s==='buildExpression')return build(RF,`Simplify (x²${a-d===0?'':` ${signedX(a-d)}`} − ${a*d})/((x−${d})(x+${a})).`,['1'],[`x + ${a}`],'The numerator factors into the same two denominator factors.');return mcq(r,RF,`Can (x+${a})/(x+${d}) be simplified by canceling x?`,['No; x is part of sums, not a common factor','Cancellation applies to multiplicative factors, not terms within addition.'],[['Yes; the result is a/d','Terms may not be canceled across addition.'],['Yes; the result is 1','The numerator and denominator are not identical.'],['Only when x is positive','Sign does not turn terms into common factors.']]);}
 if(c==='rf-unlike'){const a=pick(r,2,6),d=pick(r,1,5);return build(RF,`Subtract ${a}/(x+${d}) − 2/x.`,[`${a-2===0?`−${2*d}`:`${xterm(a-2)} − ${2*d}`}`,`/ (x(x + ${d}))`],[`${a-2}/(x+${d})`],'Use the common denominator x(x+d) and subtract the complete numerators.');}
 if(c==='rf-variation'){const x1=pick(r,2,6),y1=pick(r,4,12),x2=pick(r,2,8);const k=x1*y1,ans=k/x2;if(s==='numeric')return num(RF,`y varies inversely with x. If y=${y1} when x=${x1}, find y when x=${x2}.`,ans,[[y1*x2/x1,'This uses direct variation instead of inverse variation.'],[k,'This reports the variation constant rather than the new output.']],`The constant is k=xy=${k}; then y=${k}/${x2}.`,0.000001,{kind:'rf-variation-inverse',x1,y1,x2});return mcq(r,RF,'Which pair naturally varies inversely?',['Speed and travel time for a fixed distance','For fixed distance, increasing speed decreases time so their product stays constant.'],[['Hours worked and total pay at fixed rate','These vary directly.'],['Side length and perimeter of a square','These vary directly.'],['Number of items and total mass per item fixed','These vary directly.']]);}
 if(c==='rf-work'){const a=pick(r,3,8),b1=pick(r,a+1,12),rate=1/a+1/b1,ans=1/rate;if(s==='numeric')return num(RF,`One machine finishes a job in ${a} hours and another in ${b1} hours. How long together?`,ans,[[a+b1,'Work times do not add; rates add.'],[(a+b1)/2,'The arithmetic mean ignores different rates.']],`Add rates 1/${a}+1/${b1}, then invert the combined rate.`,0.000001,{kind:'rf-work',a,b1});return mcq(r,RF,`A pump fills a tank in ${a} hours. What fraction does it fill per hour?`,[`1/${a}`,'A complete job divided evenly across a hours gives rate 1/a job per hour.'],[[String(a),'That is the time, not the hourly fraction.'],[`1/${a*a}`,'The time is not squared.'],[`${a}/1`,'This reverses the rate.']]);}
