const SR='a2-series';
function series(r:Rand,b:Band,form:string):Variant{const [c,s]=form.split('__');
 if(c==='sr-arith-apply'){const a=pick(r,2,10),d=pick(r,1,6),n=pick(r,5,10),last=a+(n-1)*d,sum=n*(a+last)/2;if(s==='numeric')return num(SR,`An arithmetic sequence begins ${a}, ${a+d}, … and has ${n} terms. Find its sum.`,sum,[[n*(a+last),'This forgets to divide the endpoint-pair total by 2.'],[last,'This reports the final term rather than the sum.']],`Use S=n(a₁+a_n)/2=${sum}.`);return order(r,SR,`Order the steps to sum ${n} terms of an arithmetic sequence with first term ${a} and difference ${d}.`,['Find the last term','Add the first and last terms','Multiply by the number of terms','Divide by 2'],'Endpoint pairing produces the arithmetic-series formula.');}
 if(c==='sr-convert'){const a=pick(r,1,8),d=pick(r,1,6),n=pick(r,8,15),ans=a+(n-1)*d;if(s==='numeric')return num(SR,`a₁=${a}, a_n=a_(n−1)+${d}. Find a_${n}.`,ans,[[a+n*d,'This uses n increments instead of n−1.'],[a+(n-2)*d,'This uses one too few increments.']],`The explicit rule is a_n=${a}+(n−1)${d}, giving ${ans}.`);return mcq(r,SR,`Convert a₁=${a}, a_n=${d}a_(n−1) to explicit form.`,[`a_n=${a}·${d}^(n−1)`,'A geometric recursion multiplies by the common ratio once per step.'],[[`a_n=${a}+${d}(n−1)`,'That is arithmetic rather than geometric.'],[`a_n=${d}·${a}^(n−1)`,'The first term and ratio are reversed.'],[`a_n=${a}·${d}^n`,'The first term occurs at exponent zero.']]);}
 if(c==='sr-geo-apply'){const a=pick(r,1,5),q=choose(r,[2,3] as const),n=pick(r,4,8),sum=a*(q**n-1)/(q-1);if(s==='numeric')return num(SR,`A geometric payout starts at ${a} and multiplies by ${q} each week for ${n} weeks. Find the total.`,sum,[[a*q**(n-1),'This is only the final term.'],[a*(q**n)/(q-1),'The finite-sum numerator must subtract 1.']],`Use S=a(r^n−1)/(r−1)=${sum}.`);return bucket(r,SR,'Sort each question by whether it asks for one term or an accumulated total.',[['One term',['How much is paid in week 8?','What is the 12th term?']],['Series total',['How much is paid through week 8?','What is the sum of the first 12 terms?']]],'A sequence question asks for one position; a series question asks for accumulated terms.');}
 if(c==='sr-geo-derive'){const a=pick(r,1,5),q=choose(r,[2,3] as const),n=pick(r,3,6),sum=a*(q**n-1)/(q-1);return num(SR,`Evaluate ${a}+${a*q}+…+${a*q**(n-1)} using the subtract-a-shifted-copy derivation.`,sum,[[a*q**(n-1),'This is the last term only.'],[a*(q**n)/(q-1),'The derivation leaves r^n−1 in the numerator.']],`Subtracting S from qS isolates (q−1)S and gives ${sum}.`)}
 if(c==='sr-inf-apply'){const h=pick(r,5,15),[qn,qd]=choose(r,[[1,2],[2,3],[3,4]] as const),q=qn/qd,total=h+2*h*q/(1-q);return num(SR,`A ball drops ${h} m and rebounds ${qn}/${qd} of each previous height. Count all upward and later downward trips. Find total distance.`,total,[[h/(1-q),'This counts one copy of each rebound height instead of both up and down.'],[2*h/(1-q),'This doubles the initial drop, which occurs only once.']],`Total distance is h+2h·q/(1−q)=${fmt(total)}.`,0.000001)}
 if(c==='sr-inf-converge'){const q=choose(r,[0.2,0.5,0.8,1.2,-1.1] as const);return mcq(r,SR,`What happens to the infinite geometric series with common ratio ${q}?`,[Math.abs(q)<1?'Its partial sums approach a finite limit.':'It does not converge to a finite sum.',Math.abs(q)<1?'A geometric series converges exactly when |r|<1.':'Here |r|≥1, so terms do not shrink to zero.'],[[Math.abs(q)<1?'It diverges because there are infinitely many terms.':'It always converges because the terms follow a pattern.','The size of the ratio, not merely the number or pattern of terms, decides convergence.'],['Its sum is always zero','A geometric series generally has a nonzero sum.'],['Its behavior depends only on the first term','The common ratio determines whether later terms shrink.']]);}
 if(c==='sr-inf-sum'){const den=choose(r,[2,3,4] as const),a=den===3?9:den===4?3*pick(r,1,4):pick(r,2,12),q=1/den,ans=a/(1-q);return num(SR,`Find ${a}+${fmt(a*q)}+${fmt(a*q*q)}+… forever (common ratio 1/${den}).`,ans,[[a/(1+q),'The denominator is 1−r, not 1+r.'],[a*q/(1-q),'This starts from the second term and omits the first.']],`Since |r|<1, S=a/(1−r)=${fmt(ans)}.`,0.000001)}
 if(c==='sr-sigma-read'){if(s==='numeric'){const p=choose(r,[1,2,3] as const),n=pick(r,3,6),sum=Array.from({length:n},(_,i)=>(i+1)**p).reduce((a,v)=>a+v,0);return num(SR,`Evaluate Σ(k=1 to ${n}) k^${p}.`,sum,[[n**p,'This reports only the final term.'],[sum-n**p,'This omits the final term.']],`Expand every integer k from 1 through ${n} and add the powers.`)}const m=choose(r,[3,4] as const),co=choose(r,[2,3] as const),ks=Array.from({length:m},(_,i)=>i+1);return pairs(r,SR,'Match each sigma notation to its expansion.',[[`Σ(k=1 to ${m}) k`,ks.join('+')],[`Σ(k=1 to ${m}) k²`,ks.map(k=>k*k).join('+')],[`Σ(k=1 to ${m}) ${co}k`,ks.map(k=>co*k).join('+')]],'Each sigma is expanded by substituting every integer index in its stated range.');}
 if(c==='sr-sigma-write'){const n=pick(r,5,10),q=pick(r,2,5);if(s==='numeric')return num(SR,`The sum ${q}+${2*q}+…+${n*q} is Σ(k=1 to N) ${q}k. Find N.`,n,[[n*q,'That is the final term, not the upper index.'],[n-1,'This stops one term too early.']],`The last term ${n*q} occurs when k=${n}.`);return mcq(r,SR,`Which sigma represents 1²+2²+…+${n}²?`,[`Σ(k=1 to ${n}) k²`,'The index runs through the bases and each term squares the index.'],[[`Σ(k=1 to ${n}) 2k`,'This produces even numbers, not squares.'],[`Σ(k=0 to ${n}) k²`,'This includes an extra zero term; while numerically equal, it does not match the stated indexing exactly.'],[`Σ(k=1 to ${n*n}) k`,'This changes both the terms and the upper bound.']]);}
 throw new Error(`unsupported ${SR} ${form}`)}

const SI='a2-statistics';
function statistics(r:Rand,b:Band,form:string):Variant{const [c,s]=form.split('__');
 const conceptual=(prompt:string,correct:[string,string],wrong:Array<[string,string]>)=>mcq(r,SI,prompt,correct,wrong);
 if(c==='si-bias-vs-variability')return conceptual('A huge voluntary online poll is strongly biased. What does the huge sample mainly improve?',['It reduces random variability but does not remove selection bias.','Large n tightens the estimate around the biased center.'],[['It removes all bias','Sample size cannot repair a nonrepresentative selection process.'],['It proves causation','A survey design does not create random assignment.'],['It makes the population parameter equal the sample statistic','Sampling error may shrink, but the statistic is still an estimate.']]);
 if(c==='si-bias'){if(s==='dragBucket')return bucket(r,SI,'Sort each survey flaw by its primary source of bias.',[['Selection bias',['Poll only visitors to a fan website','Survey only volunteers who click a link']],['Response bias',['Ask a leading question','Ask about illegal behavior face to face']]],'Selection changes who enters the sample; response bias changes how sampled people answer.');return conceptual('Which survey question is least biased?',['How many hours did you exercise last week?','It asks for a concrete quantity without praise, blame, or a suggested answer.'],[['Don’t you agree exercise is essential?','The wording pushes respondents toward agreement.'],['How often do you make the healthy choice to exercise?','The value-laden phrase encourages socially desirable answers.'],['Why do you avoid enough exercise?','The question assumes the respondent exercises too little.']]);}
 if(c==='si-causation'){if(s==='dragBucket')return bucket(r,SI,'Sort each explanation of an association.',[['Possible confounder',['Larger fires cause both more damage and more firefighters','Age affects both medication use and health']],['Direct causal mechanism',['Random assignment changes only the treatment','A controlled intervention changes the outcome pathway']]],'A confounder influences both variables; a randomized intervention can isolate a causal pathway.');return conceptual('An observational study finds breakfast eaters score higher. What is the main limitation?',['The association may reflect confounding rather than a breakfast effect.','Other differences between breakfast eaters and non-eaters may explain the score gap.'],[['The sample is automatically too small','Sample size is separate from confounding.'],['The result proves breakfast lowers scores','The observed direction is opposite and still noncausal.'],['Observational data can never show any association','They can estimate associations, but not isolate causation reliably.']]);}
 if(c==='si-ci-meaning'){if(s==='matchPairs')return pairs(r,SI,'Match each change to its effect on a confidence interval.',[['Larger sample','Narrower interval'],['Higher confidence level','Wider interval from higher confidence'],['More variable data','Wider interval from more variability'],['Smaller sample','Wider interval from less information']],'Interval width reflects information, confidence, and variability.');return conceptual('A 95% confidence interval is 44% to 52%. Which statement is appropriate?',['The method is designed to capture the population proportion in about 95% of repeated samples.','Confidence describes the long-run performance of the interval procedure.'],[['There is a 95% probability this fixed interval contains the fixed parameter','After sampling, the classical parameter and interval are fixed.'],['95% of individuals fall between 44% and 52%','The interval estimates a population proportion, not individual values.'],['The sample proportion must be 48% exactly','The midpoint often is the estimate, but rounding or asymmetric methods can differ.']]);}
 if(c==='si-claim-capstone'){if(s==='dragBucket')return bucket(r,SI,'Sort each finding by whether immediate action is justified.',[['Act cautiously',['Randomized trial shows a meaningful benefit with narrow uncertainty','Replicated experiment shows a practically important effect']],['Wait or investigate',['Tiny effect is statistically significant only because n is enormous','Voluntary poll conflicts with representative samples']]],'Action requires credible design, practical importance, and uncertainty small enough for the decision.');return conceptual('A voluntary survey of 300,000 app users reports 78% satisfaction. What question should be asked first?',['Who was able and willing to respond?','A very precise estimate can still target the wrong population because of selection bias.'],[['Is the margin of error below 1%?','Precision cannot repair a biased sample.'],['Was the percentage rounded?','Rounding is secondary to representativeness.'],['Was the sample larger than 1,000?','The sample is already huge; design is the main concern.']]);}
 if(c==='si-claim-design'){if(s==='matchPairs')return pairs(r,SI,'Match each study design to the strongest supported claim.',[['Random sample survey','Generalize an association to the sampled population'],['Randomized experiment','Support a causal effect for the experimental units'],['Convenience sample','Describe only the observed sample cautiously'],['Census of the whole population','State the population value without sampling error']],'Random sampling supports generalization; random assignment supports causation.');return conceptual('An observational study finds app users sleep longer. Which claim is defensible?',['App use is associated with longer sleep in the studied population.','The design supports an association, not a causal effect.'],[['The app causes longer sleep','Without random assignment, confounding remains.'],['Everyone will sleep longer if they use the app','This overgeneralizes and claims causation.'],['The app has no relationship with sleep','The observed association contradicts that statement.']]);}
 if(c==='si-claim-overreach'){if(s==='numeric'){const N=choose(r,[10000,20000] as const),prev=choose(r,[0.01,0.02,0.04,0.05] as const),sens=0.95,fpr=0.05,ans=N*prev*sens+N*(1-prev)*fpr;return num(SI,`In ${N} people, prevalence is ${prev*100}%, sensitivity is 95%, and false-positive rate is 5%. How many positive tests are expected?`,ans,[[N*prev*sens,'This counts true positives but omits false positives.'],[N*fpr,'This applies the false-positive rate to everyone, including diseased people.']],`Add true positives and false positives to obtain ${ans}.`,0,{kind:'diagnostic-total',N,prev})}return conceptual('A random sample from one city station finds 61% support a fare freeze. Which claim overreaches?',['61% of all national commuters support a fare freeze.','The sampling frame covers one location, not the national commuter population.'],[['About 61% of sampled station commuters support it','This describes the sample.'],['The station result estimates support among similar station users','This is cautious about the target population.'],['Sampling variability should be reported','Uncertainty is relevant rather than an overreach.']]);}
 if(c==='si-experiment-design')return conceptual('A treatment group recovers at 90%. What is missing before attributing recovery to the treatment?',['A comparable control group with random assignment','Without a control and random assignment, natural recovery and confounding cannot be separated.'],[['A larger percentage','The observed percentage alone cannot establish causation.'],['A more complicated formula','Design, not algebraic complexity, is missing.'],['A voluntary response survey','That would add selection bias rather than causal control.']]);
 if(c==='si-margin'){if(s==='dragBucket')return bucket(r,SI,'Sort changes by their effect on margin of error.',[['Shrinks margin',['Increase sample size','Use a lower confidence level']],['Does not necessarily shrink margin',['Increase population size from one million to ten million','Use more leading wording']]],'Margin depends mainly on sample size, variability, and confidence level, not a huge population size.');if(s==='numeric'){const n=choose(r,[100,256,400,625,1600,2500,6400,10000] as const),p=0.5,moe=2*Math.sqrt(p*(1-p)/n)*100;return num(SI,`For p-hat=0.5 and n=${n}, estimate the 2-SE margin of error in percentage points.`,moe,[[Math.sqrt(p*(1-p)/n),'This is a decimal standard error, not a two-SE percentage-point margin.'],[moe/2,'This gives one standard error rather than two.']],`2√(p(1−p)/n)×100=${fmt(moe)} percentage points.`,0.1)}return conceptual('A poll reports 48% with margin of error 3 points. Which interval matches?',['45% to 51%','Add and subtract three percentage points from the estimate.'],[['48% to 51%','The margin applies in both directions.'],['3% to 48%','The margin is not an endpoint.'],['45% to 48%','This includes only the lower half.']]);}
 if(c==='si-null-model'){if(s==='dragOrder')return order(r,SI,'Order the steps of a randomization test.',['State the null model','Shuffle labels under the null','Recompute the statistic many times','Compare the observed statistic with the null distribution'],'The test first defines chance behavior, simulates it, then locates the observation.');return conceptual('What assumption is represented when labels are shuffled in a randomization test?',['The null hypothesis that the labels are unrelated to outcomes.','Shuffling destroys any systematic group effect while preserving the observed values.'],[['The alternative hypothesis is certainly true','The shuffle models no effect, not the alternative.'],['Every observation becomes independent of all others','The exact design determines dependence; the key is exchangeability under the null.'],['The sample becomes representative','Shuffling does not change the sampling process.']]);}
 if(c==='si-parameter-statistic'){if(s==='matchPairs')return pairs(r,SI,'Match each quantity to its role.',[['Population mean μ','Population parameter'],['Sample mean x-bar','Sample statistic'],['Population proportion p','Population proportion parameter'],['Sample proportion p-hat','Sample proportion statistic']],'Parameters describe populations; statistics are computed from samples.');return conceptual('Twenty small polls vary widely around the same center. What does that show?',['The statistic has high sampling variability at this sample size.','Repeated samples can produce different estimates even with honest random sampling.'],[['The population parameter changes between every poll','The target parameter is treated as fixed.'],['Every poll is biased','Variation alone does not imply systematic bias.'],['A larger sample would vary more','Larger samples usually reduce sampling variability.']]);}
 if(c==='si-pvalue-idea'){if(s==='numeric'){const extreme=pick(r,3,15),total=choose(r,[100,200,250,500] as const),ans=100*extreme/total;return num(SI,`${extreme} of ${total} null-model simulations are at least as extreme as observed. Find the p-value as a percentage.`,ans,[[extreme/total,'This is a decimal proportion, not a percentage.'],[100*(total-extreme)/total,'This counts non-extreme simulations.']],`The p-value is ${extreme}/${total}×100=${fmt(ans)}%.`,0.1)}return conceptual('A p-value of 0.79 means what?',['Results at least this extreme are common under the null model.','A large p-value indicates the observation is not unusual if the null is true.'],[['There is a 79% chance the null hypothesis is true','A p-value is conditional on the null; it is not a probability that the hypothesis is true.'],['The alternative is proven false','Failure to find evidence is not proof of no effect.'],['The effect size is 79%','The p-value is not the magnitude of the effect.']]);}
 if(c==='si-read-poll'){if(s==='dragBucket')return bucket(r,SI,'Sort poll headlines by whether the intervals justify the claim.',[['Supported',['Candidates are separated by more than combined uncertainty','A difference remains after accounting for margins']],['Not supported',['Two estimates differ by 2 points with ±3-point margins','The intervals overlap substantially']]],'Headline certainty should reflect the uncertainty intervals, not point estimates alone.');if(s==='dragOrder')return order(r,SI,'Order the questions that best protect a poll interpretation.',['Who was sampled and how?','What is the margin of error?','What population and wording are claimed?','Does the headline stay within what the interval supports?'],'Design comes before precision, and both come before broad interpretation.');return conceptual('Candidate A has 48%, B has 45%, each with ±3 points. What is justified?',['The poll does not clearly establish a leader.','The uncertainty intervals overlap.'],[['A definitely leads by 3 points','The observed gap is no larger than the reported margin.'],['B definitely leads','The point estimates show the opposite direction.'],['The candidates are exactly tied','Overlapping intervals do not prove exact equality.']]);}
 if(c==='si-sampling-dist'){if(s==='numeric'){const n=choose(r,[25,100,225,400,900] as const),factor=choose(r,[2,3,4,5] as const);return num(SI,`A poll with n=${n} has a standard error of about 1/√n. What sample size cuts the error by factor ${factor}?`,n*factor*factor,[[n*factor,'Standard error scales with the square root, so sample size must grow by the square.'],[n/factor,'Reducing variability requires increasing, not decreasing, sample size.']],`Multiply sample size by ${factor}² to divide standard error by ${factor}.`)}return conceptual('What happens to a sampling distribution when n increases substantially?',['It becomes narrower around the same parameter if the estimator is unbiased.','Standard error decreases roughly as 1/√n.'],[['Its center necessarily shifts upward','Sample size changes spread, not systematic center.'],['It becomes wider','Larger samples reduce random variability.'],['It becomes biased','Bias comes from design or estimator choice, not n alone.']]);}
 if(c==='si-sampling-variability')return conceptual('Repeated honest random samples land on both sides of the true value. What does the center of their estimates indicate?',['Whether the estimator is centered on the population parameter.','A centered sampling distribution indicates little systematic bias.'],[['The exact result of the next sample','The next statistic remains random.'],['The population size','The center estimates the parameter, not the population count.'],['The margin of error of one individual','Sampling variability concerns statistics, not individual uncertainty.']]);
 if(c==='si-significance-limits'){if(s==='dragBucket')return bucket(r,SI,'Sort findings by whether practical action is justified.',[['Potentially actionable',['Moderate meaningful effect with credible design and narrow uncertainty','Replicated benefit large enough to matter']],['Not yet actionable',['0.3-point gain on a 100-point scale despite tiny p-value','Biased survey with an extremely precise percentage']]],'Statistical significance must be combined with design quality and practical importance.');return conceptual('A huge randomized study finds a 0.3-point score increase with p<0.001. What is the best conclusion?',['The effect is statistically detectable but may be too small to justify the cost.','Large samples can detect effects that have little practical importance.'],[['The program is automatically worth buying','A decision also depends on effect size, cost, and alternatives.'],['The result must be due to bias','Randomization supports causation, though practical value remains separate.'],['The effect is exactly zero','The estimate is nonzero and statistically detectable.']]);}
 if(c==='si-standard-error'){if(s==='numeric'){const n=choose(r,[100,256,400,625,1600,2500,6400,10000] as const),p=0.5,ans=100*Math.sqrt(p*(1-p)/n);return num(SI,`Estimate the standard error in percentage points for p=0.5 and n=${n}.`,ans,[[ans*2,'This is an approximate two-standard-error margin, not one standard error.'],[Math.sqrt(p*(1-p)/n),'This is the decimal scale rather than percentage points.']],`SE=√(p(1−p)/n)×100=${fmt(ans)} ${ans===1?'point':'points'}.`,0.1,{kind:'standard-error',n,mult:1})}return conceptual('Two 1,000-person polls sample from populations of 100,000 and 100 million. Which has noticeably smaller standard error?',['Neither; with tiny sampling fractions their standard errors are nearly the same.','For large populations, sample size matters much more than population size.'],[['The poll from 100 million','A larger population does not make the same sample more precise.'],['The poll from 100,000','The finite-population correction is negligible at this sampling fraction.'],['Both have zero error','Random samples still vary.']]);}
 if(c==='si-study-type'){if(s==='matchPairs')return pairs(r,SI,'Match each design to its strongest conclusion.',[['Randomized experiment','Causal effect'],['Random sample observational study','Population association'],['Convenience survey','Sample description only'],['Census','Exact population description']],'Random assignment addresses causation; random sampling addresses generalization.');return conceptual('Researchers follow adults for ten years without assigning exercise. What type of study is this?',['Observational study','The researchers observe existing behavior rather than assign treatment.'],[['Randomized experiment','Random assignment does not occur in this design.'],['Census','Only a sample of adults is followed.'],['Simulation','The outcomes are observed in real participants.']]);}
 throw new Error(`unsupported ${SI} ${form}`)}

const TF='a2-trig';
function trig(r:Rand,b:Band,form:string):Variant{const [c,s]=form.split('__');
 if(c==='tf-amp-period'){const A=pick(r,2,7),k=pick(r,-5,5);return num(TF,`Find the minimum of y=${A}sin(x) ${sign(k)}.`,k-A,[[k+A,'That is the maximum.'],[-A,'This omits the vertical shift.']],`Since sin ranges from −1 to 1, the minimum is ${k}−${A}=${k-A}.`)}
 if(c==='tf-arc-length'){const rad=pick(r,2,9),den=choose(r,[2,3,4,6] as const),theta=Math.PI/den,ans=rad*theta;return num(TF,`A circle has radius ${rad} and central angle π/${den}. Find arc length to hundredths.`,ans,[[theta,'This omits the radius.'],[rad*Math.PI*den,'The angle denominator should divide π.']],`Use s=rθ=${rad}·π/${den}.`,0.01)}
 if(c==='tf-exact-values'){const data=choose(r,[['sin',30,0.5],['cos',60,0.5],['sin',45,Math.SQRT1_2],['cos',45,Math.SQRT1_2],['tan',45,1],['cos',30,Math.sqrt(3)/2],['sin',60,Math.sqrt(3)/2],['tan',30,1/Math.sqrt(3)],['tan',60,Math.sqrt(3)]] as const);return num(TF,`Find ${data[0]} ${data[1]}° to hundredths.`,data[2],[[1-data[2],'This confuses the ratio with a complementary value.'],[data[2]*data[2],'This squares the trigonometric value.']],`The unit-circle exact value rounds to ${round(data[2],2)}.`,0.01)}
 if(c==='tf-identity'){const sin=choose(r,[0.28,0.3,0.352,0.4,0.5,0.6,0.8,0.96] as const),cos=Math.sqrt(1-sin*sin);if(s==='numeric')return num(TF,`sin θ=${sin} and θ is in Quadrant I. Find cos θ.`,cos,[[-cos,'Quadrant I requires a positive cosine.'],[1-sin,'The identity uses squares, not direct subtraction.']],`cos θ=√(1−sin²θ)=${fmt(cos)}.`,0.001);return mcq(r,TF,'Why does solving cos²θ=0.64 first give cosθ=±0.8?',['Both 0.8 and −0.8 have square 0.64.','Squaring removes sign, so both signs are algebraic candidates.'],[['Cosine is always positive','Cosine is negative in Quadrants II and III.'],['The angle must have two values only','The sign step concerns the ratio; periodic angles may yield more solutions.'],['Square roots never have a principal value','The principal root is positive, but solving an equation requires both signs.']]);}
 if(c==='tf-inverse'){const opp=pick(r,2,8),adj=pick(r,2,8),ans=180/Math.PI*Math.atan(opp/adj);return num(TF,`A right triangle has opposite side ${opp} and adjacent side ${adj}. Find θ in degrees to tenths.`,ans,[[Math.atan(opp/adj),'This is in radians rather than degrees.'],[180/Math.PI*Math.atan(adj/opp),'This reverses opposite and adjacent.']],`θ=tan⁻¹(${opp}/${adj})≈${round(ans,1)}°.`,0.1)}
 if(c==='tf-model'){const mid=pick(r,15,30),A=pick(r,5,12),T=choose(r,[20,24,30] as const);if(s==='numeric')return num(TF,`For h(t)=${mid}−${A}cos(2πt/${T}), find h(${T/2}).`,mid+A,[[mid-A,'That is the value at t=0.'],[mid,'That is the midline, not the opposite extreme.']],`At half a period cosπ=−1, so h=${mid}+${A}.`);return mcq(r,TF,'Why might a ride-height model begin with −A cos(ωt) instead of +A sin(ωt)?',['It starts at the minimum height when t=0.','cos0=1, so a negative cosine begins A units below the midline.'],[['Sine and cosine are unrelated','They are phase-shifted versions of the same wave family.'],['Negative cosine has no period','Its period is unchanged by reflection.'],['It makes the amplitude negative','Amplitude is the positive magnitude |A|.']]);}
 if(c==='tf-ratios'){if(s==='dragBucket')return bucket(r,TF,'Sort each side description relative to angle θ.',[['Opposite',['Across from θ','Does not touch θ']],['Adjacent',['Touches θ but is not the hypotenuse','Forms θ with the hypotenuse']],['Hypotenuse',['Opposite the right angle','Longest side']]],'Side names depend on the marked angle and the right angle.');const triples=choose(r,[[3,4,5],[5,12,13],[8,15,17],[7,24,25],[9,40,41],[20,21,29],[12,35,37]] as const),opp=triples[0],adj=triples[1],hyp=triples[2];return num(TF,`In a ${opp}-${adj}-${hyp} right triangle, θ is opposite ${opp}. If cosθ=n/${hyp}, find n.`,adj,[[opp,'This is the opposite side used by sine.'],[hyp,'The hypotenuse is already the denominator.']],`Cosine is adjacent over hypotenuse, so n=${adj}.`)}
 if(c==='tf-reference'){const q=choose(r,[2,3,4] as const),ref=choose(r,[30,45,60] as const),angle=q===2?180-ref:q===3?180+ref:360-ref;return num(TF,`Find the reference angle of ${angle}°.`,ref,[[angle-ref,'This gives an axis angle rather than the acute reference angle.'],[180-ref,'This rule works only in Quadrant II.']],`The acute angle to the nearest x-axis is ${ref}°.`)}
 if(c==='tf-solve-sides'){const hyp=choose(r,[8,10,12,14] as const),angle=choose(r,[30,45,60] as const),ans=hyp*Math.sin(angle*Math.PI/180);return num(TF,`A ramp of length ${hyp} meets the ground at ${angle}°. Find its vertical rise.`,ans,[[hyp*Math.cos(angle*Math.PI/180),'This finds the horizontal run.'],[hyp*Math.tan(angle*Math.PI/180),'Tangent uses the adjacent side rather than the hypotenuse.']],`The rise is opposite the angle, so use ${hyp}sin${angle}°.` ,0.01)}
 if(c==='tf-transform'){const B=choose(r,[0.25,0.5,2,3,4,5,6,8] as const),period=2*Math.PI/Math.abs(B);return num(TF,`Find the period of y=cos(${B}x).`,period,[[2*Math.PI*B,'The frequency factor divides the parent period.'],[Math.PI/Math.abs(B),'This gives half the full cycle.']],`Period=2π/|B|=${fmt(period)}.`,0.01)}
 if(c==='tf-unit-circle'){const angle=choose(r,[0,90,180,270,360,450,540,630] as const),cos=Math.cos(angle*Math.PI/180),sin=Math.sin(angle*Math.PI/180);if(s==='numeric')return num(TF,`Find cos ${angle}°.`,round(cos),[[round(sin),'This uses the y-coordinate instead of the x-coordinate.'],[-round(cos),'This reverses the unit-circle x-coordinate sign.']],`Cosine is the x-coordinate, ${round(cos)}.`);return mcq(r,TF,'In which quadrant are both sine and cosine negative?',['Quadrant III','Both x- and y-coordinates are negative there.'],[['Quadrant I','Both are positive.'],['Quadrant II','Sine is positive and cosine negative.'],['Quadrant IV','Cosine is positive and sine negative.']]);}
 if(c==='tf-wave-read'){const A=pick(r,2,7),k=pick(r,-4,4);return num(TF,`Find the maximum value of y=${A}sin x ${sign(k)}.`,k+A,[[k-A,'That is the minimum.'],[A,'This omits the vertical shift.']],`The maximum occurs when sinx=1, giving ${k+A}.`)}
 throw new Error(`unsupported ${TF} ${form}`)}

